-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONTACTOS_HIST_UPDATE` AFTER UPDATE ON `FB_CONTACTOS` FOR EACH ROW
BEGIN
IF NEW.VERSION>OLD.VERSION THEN INSERT INTO FB_CONTACTOS_HISTORIAL (ID_CONTACTO,ID_CONSULTA,VERSION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_CONTACTO,NEW.ID_CONSULTA,NEW.VERSION,NEW.USUARIO_MODIFICADOR_ID,JSON_OBJECT('id_contacto',CAST(OLD.`ID_CONTACTO` AS CHAR),'id_consulta',CAST(OLD.`ID_CONSULTA` AS CHAR),'telefono_1',OLD.`TELEFONO_1`,'tipo_telefono_1',OLD.`TIPO_TELEFONO_1`,'telefono_2',OLD.`TELEFONO_2`,'tipo_telefono_2',OLD.`TIPO_TELEFONO_2`,'telefono_3',OLD.`TELEFONO_3`,'tipo_telefono_3',OLD.`TIPO_TELEFONO_3`,'telefono_4',OLD.`TELEFONO_4`,'tipo_telefono_4',OLD.`TIPO_TELEFONO_4`,'telefono_5',OLD.`TELEFONO_5`,'tipo_telefono_5',OLD.`TIPO_TELEFONO_5`,'mail_1',OLD.`MAIL_1`,'mail_2',OLD.`MAIL_2`,'mail_3',OLD.`MAIL_3`,'mail_4',OLD.`MAIL_4`,'mail_5',OLD.`MAIL_5`,'fecha_alta',OLD.`FECHA_ALTA`,'nombre_completo',OLD.`NOMBRE_COMPLETO`,'tipo_documento',OLD.`TIPO_DOCUMENTO`,'documento',OLD.`DOCUMENTO`,'documento_normalizado',OLD.`DOCUMENTO_NORMALIZADO`,'usuario_modificador_id',OLD.`USUARIO_MODIFICADOR_ID`,'fecha_modificacion',OLD.`FECHA_MODIFICACION`,'version',OLD.`VERSION`,'id_persona',CAST(OLD.`ID_PERSONA` AS CHAR)),JSON_OBJECT('id_contacto',CAST(NEW.`ID_CONTACTO` AS CHAR),'id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'telefono_1',NEW.`TELEFONO_1`,'tipo_telefono_1',NEW.`TIPO_TELEFONO_1`,'telefono_2',NEW.`TELEFONO_2`,'tipo_telefono_2',NEW.`TIPO_TELEFONO_2`,'telefono_3',NEW.`TELEFONO_3`,'tipo_telefono_3',NEW.`TIPO_TELEFONO_3`,'telefono_4',NEW.`TELEFONO_4`,'tipo_telefono_4',NEW.`TIPO_TELEFONO_4`,'telefono_5',NEW.`TELEFONO_5`,'tipo_telefono_5',NEW.`TIPO_TELEFONO_5`,'mail_1',NEW.`MAIL_1`,'mail_2',NEW.`MAIL_2`,'mail_3',NEW.`MAIL_3`,'mail_4',NEW.`MAIL_4`,'mail_5',NEW.`MAIL_5`,'fecha_alta',NEW.`FECHA_ALTA`,'nombre_completo',NEW.`NOMBRE_COMPLETO`,'tipo_documento',NEW.`TIPO_DOCUMENTO`,'documento',NEW.`DOCUMENTO`,'documento_normalizado',NEW.`DOCUMENTO_NORMALIZADO`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'version',NEW.`VERSION`,'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR))); END IF;
END$$
DELIMITER ;
